        pass
    @pytest.mark.xfail('left')
    class Left(Root):
        pass
    @pytest.mark.xfail('right')
    class Right(Root):
        pass
    @pytest.mark.xfail('leaf')
    class Leaf(Left, Right):
        pass
    assert labels(Leaf) == ['leaf', 'left', 'right', 'root']


